using System.Diagnostics;

public static class Coop
{
    private static int _liveRegistrations;

    /// Number of registrations Coop currently holds on caller-supplied tokens (diagnostic hook
    /// for the leak test). Must return to 0 once every returned task has completed.
    public static int LiveRegistrations => Volatile.Read(ref _liveRegistrations);

    /// Runs <paramref name="operation"/> with a token that is cancelled when the caller's token is
    /// cancelled or when <paramref name="timeout"/> elapses, whichever comes first.
    public static async Task<T> WithTimeoutAsync<T>(
        Func<CancellationToken, Task<T>> operation,
        TimeSpan timeout,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(operation);
        if (timeout < TimeSpan.Zero && timeout != Timeout.InfiniteTimeSpan)
            throw new ArgumentOutOfRangeException(nameof(timeout));

        cancellationToken.ThrowIfCancellationRequested();

        // Fast path: no timer, no linked source, nothing to dispose.
        if (timeout == Timeout.InfiniteTimeSpan)
            return await operation(cancellationToken).ConfigureAwait(false);

        // The linked source registers a callback on the caller's token; disposing it removes
        // that registration, so a long-lived caller token does not accumulate garbage.
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        linked.CancelAfter(timeout);
        Interlocked.Increment(ref _liveRegistrations);

        try
        {
            return await operation(linked.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException oce) when (cancellationToken.IsCancellationRequested)
        {
            // The caller asked to stop: surface it as *their* cancellation, not the linked token's.
            throw new OperationCanceledException(oce.Message, oce, cancellationToken);
        }
        catch (OperationCanceledException oce) when (linked.IsCancellationRequested)
        {
            // Only the timer fired: this is a failure, not a cancellation.
            throw new TimeoutException($"The operation did not complete within {timeout}.", oce);
        }
        finally
        {
            Interlocked.Decrement(ref _liveRegistrations); // `using` disposes `linked` right after this
        }
        // Any other exception (including an OCE thrown for a token we do not own) propagates unchanged.
    }

    /// Makes waiting on <paramref name="task"/> cancellable. The task itself keeps running.
    public static Task<T> WithCancellationAsync<T>(this Task<T> task, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(task);

        if (task.IsCompleted || !cancellationToken.CanBeCanceled)
            return task;

        if (cancellationToken.IsCancellationRequested)
        {
            ObserveFault(task);
            return Task.FromCanceled<T>(cancellationToken);
        }

        return Race(task, cancellationToken);

        static async Task<T> Race(Task<T> task, CancellationToken ct)
        {
            var tcs = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);

            // Static lambda + state object: no closure allocation. The registration is removed in the
            // implicit finally of `using` whichever branch wins, so the token's callback list never grows.
            using CancellationTokenRegistration reg = ct.UnsafeRegister(
                static (state, token) => ((TaskCompletionSource<bool>)state!).TrySetCanceled(token), tcs);
            Interlocked.Increment(ref _liveRegistrations);

            try
            {
                Task completed = await Task.WhenAny(task, tcs.Task).ConfigureAwait(false);
                if (ReferenceEquals(completed, task))
                    return await task.ConfigureAwait(false); // propagates result, fault, or cancellation

                ObserveFault(task);
                throw new OperationCanceledException(ct);
            }
            finally
            {
                Interlocked.Decrement(ref _liveRegistrations);
            }
        }
    }

    // A task we walk away from must not raise TaskScheduler.UnobservedTaskException later.
    private static void ObserveFault(Task task) =>
        task.ContinueWith(static t => _ = t.Exception,
            CancellationToken.None,
            TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);
}

